 11	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
 12	
 13	interface Frame {
 14	  type: string;
 15	  sessionId?: string;
 16	  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
 17	  code?: string;
 18	  message?: string;
 19	}
 20	
 21	const servers: Array<ReturnType<typeof createServer>> = [];
 22	const clients: WebSocket[] = [];
 23	const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
 24	
 25	const eventually = async (check: () => boolean): Promise<void> => {
 26	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
 27	};
 28	
 29	beforeEach(() => {
 30	  logLines.length = 0;
 31	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
 32	    void logLines.push({level, category, message, fields});
 33	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
 34	});
 35	
 36	afterEach(async () => {
 37	  for (const client of clients.splice(0)) client.terminate();
 38	  for (const hal of servers.splice(0)) {
 39	    const {wss} = hal;
 40	    await eventually(() => wss.clients.size === 0);
 41	    await hal.stop();
 42	  }
 43	  setLogger();
 44	});
 45	
 46	const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
 47	  const hal = createServer({
 48	    app: (() => undefined) as unknown as Express,
 49	    wsAuth: async () => ({id: userId}),
 50	    sessionStore: store,
 51	    orchestrator: answeringOrchestrator,
 52	  });
 53	  await hal.start(0);
 54	  servers.push(hal);
 55	  const {port} = hal.server.address() as AddressInfo;
 56	  return `ws://127.0.0.1:${port}/hal/ws`;
 57	};
 58	
 59	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
 60	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
 61	  clients.push(client);
 62	  const frames: Frame[] = [];
 63	  let connected: Frame = {type: ''};
 64	  await new Promise<void>(resolve => {
 65	    client.on('message', raw => {
 66	      const frame = JSON.parse(String(raw)) as Frame;
 67	      if (frame.type === 'connected') {
 68	        connected = frame;
 69	        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
 70	        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
 71	        return;
 72	      }
 73	      if (frame.type === 'pong') {
 74	        resolve();
 75	        return;
 76	      }
 77	      frames.push(frame);
 78	    });
 79	  });
 80	  return {connected, frames};
 81	};
 82	
 83	// A store with only the five required members, so listFor can be omitted, recorded or made to throw.
 84	const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
 85	  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
 86	  get: sessionId => inner.get(sessionId),
 87	  delete: sessionId => inner.delete(sessionId),
 88	  count: () => inner.count(),
 89	  clear: () => inner.clear(),
 90	});
 91	
 92	describe('listing conversations over the WebSocket protocol', () => {
